insert into audit_backup.rewrites_20261122_proposals (locale, slug, field, col, path, decision, old_text, new_text)
values
  ('en', 'harz-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'In [dated source] Harz became the first National Park in Germany to cover two federal states; the eastern part in Sachsen-Anhalt consists of 8,900 ha of land and was set up in 1990. In 1994, the federal government of Niedersachsen established the western part of the park, covering 15,800 ha. As a result, the united Harz National Park consists of approximately 24,700 ha. The Park is part of Natura [dated source] – the European nature conservation – network.

Harz National Park stretches from a low mountain range near Herzberg in the southern part of the mountains, across the Harz massif to its northern slopes near Bad Harzburg and Ilsenburg. It offers the entire range of characteristic ecological systems, variations in height, slopes and rocks. Height varies from approximately 240 m in the north and 270 m on the southern edge up to 1,141 m on Brocken peak. The Park offers an ecologically complex landscape and contains different vegetation zones.

Harz National Park is virtually uninhabited, but does contain some settlements. Nearly all the land within the Park is forested and belongs to the federal states.

Scientific research has identified numerous habitats which are, based on Middle-European standards, quite close to a natural state, such as the high and middle regions or zones of the Harz, rocky biotopes, many running waters, and a large beech, spruce and mixed forest area. In some sections, however, ecological changes in afforestation must be carried out in order to get closer to original, natural forest conditions.', 'Harz National Park covers two federal states: the eastern part in Saxony-Anhalt, set up in 1990, has 8,900 ha of land, and the western part, established by Niedersachsen in 1994, covers 15,800 ha. Together the park covers about 24,700 ha and is part of Natura 2000, the European nature conservation network.

The park stretches from the low hills near Herzberg in the south, across the Harz massif, to its northern slopes near Bad Harzburg and Ilsenburg. It spans the full range of characteristic ecosystems, altitudes, slopes and rocks, from about 240 m in the north and 270 m on the southern edge up to 1,141 m on the Brocken, with several vegetation zones.

The park is virtually uninhabited, though it contains a few settlements. Almost all of its land is forested and owned by the federal states.

Research has identified many habitats that are close to a natural state by Central European standards, such as the high and middle zones of the Harz, rocky biotopes, many streams and a large area of beech, spruce and mixed forest. In some sections, however, forest management is still needed to bring the forest closer to its original natural condition.'),
  ('en', 'hump-ridge-track', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Hump Ridge Track, also called the Tuatapere Hump Ridge Track, is a 60–62 km walking track that is partly in Fiordland National Park in New Zealand. The track was opened in [dated source] and is run privately on behalf of the Tuatapere Hump Ridge Track Charitable Trust.', 'The Hump Ridge Track, also called the Tuatapere Hump Ridge Track, is a 60–62 km walking track partly within Fiordland National Park in New Zealand. It is run privately on behalf of the Tuatapere Hump Ridge Track Charitable Trust.'),
  ('en', 'jizerskohorske-buciny', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Jizera mountain beech is a national nature reserve, which was created on 16 August 1999 by the merger of the original seven national nature reserves Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantský cimmburi and Paličík by Decree No. 200 / 1999. In July [dated source] they became the first Czech natural monument included in the UNESCO World Heritage List.', 'The Jizera mountain beech forests (Jizerskohorské bučiny) form a national nature reserve created on 16 August 1999 by merging seven earlier reserves: Špičák, Slouvá vrch, Míledník, Štolpichy, Tistina, Frýdlantské cimbuří and Paličník. They became the first Czech natural site included on the UNESCO World Heritage List.'),
  ('en', 'junkerdal-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'The 682-square-kilometre park opened in [dated source].', 'A 682 km2 national park in Saltdal and Fauske, Nordland county, Norway, along the border with Sweden.'),
  ('en', 'junkerdal-national-park', 'tagline', 'tagline', null, 'REWRITE', 'The 682-square-kilometre park opened in [dated source].', 'A 682 km2 national park in Saltdal and Fauske, Nordland county, Norway, along the border with Sweden.'),
  ('en', 'kosterhavet-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Kosterhavet National Park is the first national marine park in Sweden, inaugurated in September [dated source]. It is part of the Skagerrak sea and is located in Strömstad and Tanum municipalities in Bohuslän, Västra Götaland County, Sweden. It consists of the sea and shores around the Koster Islands, excluding everything else on the islands. In the north, it borders the Norwegian marine park of Ytre Hvaler.', 'Kosterhavet National Park is Sweden''s first national marine park. It is part of the Skagerrak and lies in Strömstad and Tanum municipalities in Bohuslän, Västra Götaland County. It consists of the sea and shores around the Koster Islands, excluding the rest of the islands, and borders the Norwegian marine park of Ytre Hvaler to the north.'),
  ('en', 'kotychi-and-strofylia-wetlands-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'It was declared a national park in [dated source].', 'Protected wetlands and forest in Achaia and Ilia, with Kotychi Lake, the Strofylia Forest and Cape Araxos.'),
  ('en', 'kotychi-and-strofylia-wetlands-national-park', 'tagline', 'tagline', null, 'REWRITE', 'It was declared a national park in [dated source].', 'Protected wetlands and forest in Achaia and Ilia, with Kotychi Lake, the Strofylia Forest and Cape Araxos.'),
  ('en', 'langsua-national-park', 'seo_description', 'seo_description', null, 'REWRITE', 'Langsua National Park was established in [dated source].', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway.'),
  ('en', 'langsua-national-park', 'tagline', 'tagline', null, 'REWRITE', 'Langsua National Park was established in [dated source].', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway.'),
  ('en', 'langsua-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Langsua National Park was established in [dated source]. The park consists of a total protected area of 537.1-square-kilometre . It is located in Innlandet county in Norway, and covers parts of the municipalities Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron and Nord-Fron.', 'Langsua National Park protects 537.1 square kilometres in Innlandet county, Norway, covering parts of the municipalities of Øystre Slidre, Nord-Aurdal, Nordre Land, Gausdal, Sør-Fron and Nord-Fron.'),
  ('en', 'les-deux-caps-blanc-nez-gris-nez', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], its perimeter increases from eight to eighteen municipalities.', 'A Grand Site de France on the Opal Coast between Boulogne-sur-Mer and Calais, facing England.'),
  ('en', 'les-deux-caps-blanc-nez-gris-nez', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], its perimeter increases from eight to eighteen municipalities.', 'A Grand Site de France on the Opal Coast between Boulogne-sur-Mer and Calais, facing England.'),
  ('en', 'liechtensteinklamm', 'seo_description', 'seo_description', null, 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last', ''),
  ('en', 'liechtensteinklamm', 'tagline', 'tagline', null, 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last', ''),
  ('en', 'liechtensteinklamm', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'Liechtensteinklamm is open daily from begin of May until 30 September [dated source] from 09:00 to 18:00 (last admission at 18:00).', ''),
  ('en', 'lomsdal-visten-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Lomsdal–Visten National Park is a Norwegian national park that was established on 26 June [dated source]. The park consists of a total protected area of 1,102 square kilometres . It is located in Nordland county, Norway, and covers parts of Brønnøy Municipality, Vevelstad Municipality, Grane Municipality, and Vefsn Municipality.', 'Lomsdal–Visten National Park is a Norwegian national park with a protected area of 1,102 square kilometres. It lies in Nordland county and covers parts of Brønnøy, Vevelstad, Grane and Vefsn municipalities.'),
  ('en', 'loonse-en-drunense-duinen', 'seo_description', 'seo_description', null, 'REWRITE', 'It has been designated as a national park since [dated source].', 'A 35 km2 national park between Tilburg, Waalwijk and ''s-Hertogenbosch in the south of the Netherlands.'),
  ('en', 'loonse-en-drunense-duinen', 'tagline', 'tagline', null, 'REWRITE', 'It has been designated as a national park since [dated source].', 'A 35 km2 national park between Tilburg, Waalwijk and ''s-Hertogenbosch in the south of the Netherlands.'),
  ('en', 'lorship-bertiz-natural-park', 'seo_description', 'seo_description', null, 'REWRITE', 'The Natural Park Señorío de Bertiz (officially Bertizko Jaurerria Parke Naturala) [dated source] ha, is locate', 'Señorío de Bertiz is a natural park in the north-west of Navarre, Spain, declared in 1984.'),
  ('en', 'lorship-bertiz-natural-park', 'tagline', 'tagline', null, 'REWRITE', 'The Natural Park Señorío de Bertiz (officially Bertizko Jaurerria Parke Naturala) [dated source] ha, is locate', 'Señorío de Bertiz is a natural park in the north-west of Navarre, Spain, declared in 1984.'),
  ('en', 'marine-natural-park-of-picardy-and-opale-coast', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel marin des estuaires picards et de la mer d''Opale is a French marine natural park created in December [dated source]. It is located in front of the seven coastal rivers, from south to north, the Bresle, the Somme, the Authie, the Canche, the Liane, the Wimereux and the Slack. Its headquarters is located in Écault in the territory of Saint-Étienne-au-Mont, in the Pas-de-Calais.', 'The Parc naturel marin des estuaires picards et de la mer d''Opale is a French marine natural park off the mouths of seven coastal rivers: from south to north, the Bresle, the Somme, the Authie, the Canche, the Liane, the Wimereux and the Slack. Its headquarters are in Écault, in Saint-Étienne-au-Mont (Pas-de-Calais).'),
  ('en', 'marker-wadden-in-het-markermeer', 'seo_description', 'seo_description', null, 'REWRITE', 'The first island was inaugurated on 24 September [dated source].', 'The Marker Wadden is an artificial archipelago and nature reserve in the Markermeer lake, Netherlands.'),
  ('en', 'marker-wadden-in-het-markermeer', 'tagline', 'tagline', null, 'REWRITE', 'The first island was inaugurated on 24 September [dated source].', 'The Marker Wadden is an artificial archipelago and nature reserve in the Markermeer lake, Netherlands.'),
  ('en', 'mayotte-marine-natural-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Mayotte Marine Natural Park is a marine park surrounding Mayotte, a French overseas region. Mayotte is part of the Comoro Islands archipelago, which lies within the Mozambique Channel in the western Indian Ocean. Established in [dated source], the park covers the entirety of Mayotte''s territorial waters and exclusive economic zone. It is contiguous with the Glorioso Islands Marine Natural Park, which was established two years later.', 'The Mayotte Marine Natural Park surrounds Mayotte, a French overseas region in the Comoro Islands archipelago, in the Mozambique Channel of the western Indian Ocean. The park covers all of Mayotte''s territorial waters and exclusive economic zone and adjoins the Glorioso Islands Marine Natural Park.'),
  ('en', 'midden-delfland', 'seo_description', 'seo_description', null, 'REWRITE', 'It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality of 49.38 km2 in the Westland region of South Holland.'),
  ('en', 'midden-delfland', 'tagline', 'tagline', null, 'REWRITE', 'It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality of 49.38 km2 in the Westland region of South Holland.'),
  ('en', 'midden-delfland', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Midden-Delfland (Dutch: [ˌmɪdəˈdɛlflɑnt] ) is a municipality in the Westland region in the province of South Holland in the Netherlands. It had a population of 19,355 in [dated source], and covers an area of 49.38 km2 of which 2.19 km2 is water.', 'Midden-Delfland is a municipality in the Westland region of the province of South Holland in the Netherlands. It covers 49.38 km2, of which 2.19 km2 is water.'),
  ('en', 'millevaches-en-limousin', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Millevaches Regional Natural Park in Limousin is a French regional natural park created in [dated source], situated on the edge of three departments of the Nouvelle-Aquitaine region . It is, in chronological order, the second natural park of the Limousin regional territory; the first, the Perigord-Limousin park, dates from 1998. It is one of four NRPs in the new major region.', 'The Millevaches Regional Natural Park in Limousin is a French regional natural park on the edge of three departments of the Nouvelle-Aquitaine region. It is the second natural park in the Limousin area; the first, the Périgord-Limousin park, dates from 1998. It is one of four regional natural parks in the region.'),
  ('en', 'mont-ventoux', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Mont-Ventoux Regional Natural Park, in Provençal pargue dóu Ventours, is a regional natural park created by decree on 28 July [dated source]. It is the 55th regional nature park created in France, and the 9th in Provence-Alpes-Côte d''Azur.', 'The Mont-Ventoux Regional Natural Park (Provençal: pargue dóu Ventours) is the 55th regional nature park created in France and the 9th in Provence-Alpes-Côte d''Azur.'),
  ('en', 'mors-and-hanklit', 'seo_description', 'seo_description', null, 'REWRITE', 'It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486.', 'Mors is a 367.3 km2 island in the Limfjord, Denmark, known for its diatomite (moler) deposits.'),
  ('en', 'mors-and-hanklit', 'tagline', 'tagline', null, 'REWRITE', 'It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486.', 'Mors is a 367.3 km2 island in the Limfjord, Denmark, known for its diatomite (moler) deposits.'),
  ('en', 'mors-and-hanklit', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mors or Morsø is an island in the shallow sound called Limfjorden between Denmark''s Jutland peninsula and the North Jutlandic Island. It has an area of 367.3 km2 and as of 1 January [dated source], it had a population of 19,486. The main town on the island is called Nykøbing Mors. Geologically Mors is unique. Like the neighbouring island of Fur, it is known for its deposits of diatomite, locally known as ''moler'' .', 'Mors (Morsø) is an island in the Limfjord, the shallow sound between Denmark''s Jutland peninsula and the North Jutlandic Island. It has an area of 367.3 km2, and its main town is Nykøbing Mors. Geologically Mors is unique: like the neighbouring island of Fur, it is known for its deposits of diatomite, locally called ''moler''.'),
  ('en', 'morskie-oko', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Morskie Oko, or Eye of the Sea in English, is the largest and fourth-deepest lake in the Tatra Mountains, in southern Poland. It is located deep within the Tatra National Park in the Rybi Potok Valley, of the High Tatras mountain range at the base of the Mięguszowiecki Summits, in Lesser Poland Voivodeship. In [dated source], The Wall Street Journal recognized the lake as one of the five most beautiful lakes in the world.', 'Morskie Oko (''Eye of the Sea'') is the largest and fourth-deepest lake in the Tatra Mountains, in southern Poland. It lies deep within Tatra National Park in the Rybi Potok Valley of the High Tatras, at the foot of the Mięguszowiecki Summits, in Lesser Poland Voivodeship.'),
  ('en', 'nationaal-park-de-sallandse-heuvelrug', 'seo_description', 'seo_description', null, 'REWRITE', 'In [dated source], the Dutch Government changed the status of the area to National Park.', 'Sallandse Heuvelrug is a national park in Overijssel, between the townships of Hellendoorn and Holten.'),
  ('en', 'nationaal-park-de-sallandse-heuvelrug', 'tagline', 'tagline', null, 'REWRITE', 'In [dated source], the Dutch Government changed the status of the area to National Park.', 'Sallandse Heuvelrug is a national park in Overijssel, between the townships of Hellendoorn and Holten.'),
  ('en', 'nationaal-park-duinen-van-texel', 'seo_description', 'seo_description', null, 'REWRITE', 'The park covers approximately 43 km2 and attained national park status in [dated source].', 'Duinen van Texel National Park covers about 43 km2 of dunes and coastal plains on the island of Texel.'),
  ('en', 'nationaal-park-duinen-van-texel', 'tagline', 'tagline', null, 'REWRITE', 'The park covers approximately 43 km2 and attained national park status in [dated source].', 'Duinen van Texel National Park covers about 43 km2 of dunes and coastal plains on the island of Texel.'),
  ('en', 'national-park-drina', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Drina National Park is the fourth national park in Bosnia and Herzegovina, and the third in Republika Srpska. It was founded in [dated source]. The nearest town is Srebrenica. It is located on the other side of the Drina in relation to Tara National Park in Serbia.', 'Drina National Park is the fourth national park in Bosnia and Herzegovina and the third in Republika Srpska. The nearest town is Srebrenica. It lies on the opposite bank of the Drina from Tara National Park in Serbia.'),
  ('en', 'national-park-of-eastern-macedonia-and-thrace', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The National Park of Eastern Macedonia - Thrace was founded in [dated source] and included the already protected areas of D. Nestos, L. Vistonidas, L. Ismaridas and their wider area. The wetland complex of the National Park is one of the most important in Greece, due to its large area and its large biological, aesthetic, scientific, geomorphological and pedagogical value. The aim of the National Park is to effectively protect habitats and rare flora and fauna species that endemic and breed in the region.', 'The National Park of Eastern Macedonia and Thrace takes in the previously protected Nestos delta, Lake Vistonida, Lake Ismarida and their wider area. Its wetland complex is one of the most important in Greece because of its size and its great biological, aesthetic, scientific, geomorphological and educational value. The park aims to protect habitats and rare plant and animal species that are endemic to or breed in the region.'),
  ('en', 'national-park-of-messolonghi-aitoliko-lagoons', 'seo_description', 'seo_description', null, 'REWRITE', 'Created in [dated source], it encompasses the country''s largest lagoon complex.', 'The national park encompasses Greece''s largest lagoon complex, at the northwest end of the Gulf of Patras.'),
  ('en', 'national-park-of-messolonghi-aitoliko-lagoons', 'tagline', 'tagline', null, 'REWRITE', 'Created in [dated source], it encompasses the country''s largest lagoon complex.', 'The national park encompasses Greece''s largest lagoon complex, at the northwest end of the Gulf of Patras.'),
  ('en', 'nationalpark-mols-bjerge', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Mols Bjerge National Park or Nationalpark Mols Bjerge is a Danish national park in the area known as Mols Bjerge in Syddjurs Municipality, Central Jutland, inaugurated on 29 August [dated source]. The protected area, measures 180 square kilometres in size. The Mols Hills, reaching a height of 137 metres, are centrally located in the park, and take up 2,500 ha. "More than half of all wild Danish plant species" can be found at Mols Bjerge.', 'Mols Bjerge National Park (Nationalpark Mols Bjerge) is a Danish national park in the Mols Bjerge area of Syddjurs Municipality, Central Jutland. The protected area measures 180 square kilometres. The Mols Hills, rising to 137 metres, lie at the centre of the park and take up 2,500 ha. More than half of all wild Danish plant species can be found at Mols Bjerge.'),
  ('en', 'nationalpark-thy', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Thy National Park is a national park area in Thy, Denmark, opened to the public on 22 August [dated source]. It is located in Northwest Jutland, along the coast from Hanstholm to Agger Tange and it spans 55 km north to south and 5–12 km east to west. The total area of the national park is 244 km2 .', 'Thy National Park is a national park in Thy, Denmark. It lies in Northwest Jutland along the coast from Hanstholm to Agger Tange, spanning 55 km from north to south and 5–12 km from east to west. The national park covers a total of 244 km2.'),
  ('en', 'natural-park-of-serra-d-irta', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Serra d''Irta Natural Park (Valencian: Parc Natural de la Serra d''Irta, Spanish: Parque Natural de la Sierra de Irta) is a natural park in Valencian Community), Southern Spain. It contains 7,744 hectares of land, as well as a shoreline of marine nature reserve of the adjacent Mediterranean Sea. It was declared a protected area in [dated source].', 'Serra d''Irta Natural Park (Valencian: Parc Natural de la Serra d''Irta; Spanish: Parque Natural de la Sierra de Irta) is a natural park in the Valencian Community, Spain. It covers 7,744 hectares of land, together with a marine nature reserve along the adjacent Mediterranean shoreline.'),
  ('en', 'naturpark-nissum-fjord', 'seo_description', 'seo_description', null, 'REWRITE', 'The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park covers 22,670 hectares around the fjord and is Denmark''s third-largest nature park.'),
  ('en', 'naturpark-nissum-fjord', 'tagline', 'tagline', null, 'REWRITE', 'The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park covers 22,670 hectares around the fjord and is Denmark''s third-largest nature park.'),
  ('en', 'naturpark-nissum-fjord', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Natural park Nissum Fjord was set up as a pilot project at the request of the Nissum Fjord Network in May [dated source]. The nature park extends over 22.670 hectares around Nissum Fjord and is the third largest natural park in Denmark. The Nature Park was approved by the Open Air Council on 12 December [dated source].', 'Nissum Fjord Nature Park extends over 22,670 hectares around Nissum Fjord and is the third-largest nature park in Denmark.'),
  ('en', 'north-pindos-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'North Pindos National Park is 230 km long and 70 km wide, founded in [dated source] and is considered one of the most important areas at national and European level. Also, the variety in rare species should be mentioned as almost all the large mammals of mainland Greece are hosted in the area. A total of 60 species of mammals, 166 species of birds, 30 species of reptiles, 14 species of amphibians and 17 species of fish are found in the park.', 'North Pindos National Park is 230 km long and 70 km wide and is considered one of the most important areas in Greece and in Europe. Almost all the large mammals of mainland Greece live here: in total 60 species of mammals, 166 of birds, 30 of reptiles, 14 of amphibians and 17 of fish are found in the park.'),
  ('en', 'ostmarka-national-park', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'Østmarka National Park is a Norwegian national park created in [dated source]. It covers an area of 54 km2 in Østmarka, Oslo and Akershus Municipality Nordre Follo, Lørenskog, Røllen and Enebakk.', 'Østmarka National Park is a Norwegian national park covering 54 km2 of the Østmarka forest, in Oslo and in the Akershus municipalities of Nordre Follo, Lørenskog, Rælingen and Enebakk.'),
  ('en', 'paluma-range-national-park-qld', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'CLEAR', 'On National Parks Day [dated source], the Queensland State Government announced the addition of 6,510 hectares to the Paluma Range National Park.', ''),
  ('en', 'parc-naturel-regional-alpilles', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Alpilles Regional Nature Park is a French regional nature park created in [dated source], in Provence-Alpes-Côte d''Azur in the Bouches-du-Rhône department. It extends over the pre-alpine limestone massif of the Alpilles and its immediate surroundings .', 'The Alpilles Regional Nature Park is a French regional nature park in the Bouches-du-Rhône department of Provence-Alpes-Côte d''Azur. It covers the pre-alpine limestone massif of the Alpilles and its immediate surroundings.'),
  ('en', 'parc-naturel-regional-aubrac', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Aubrac Regional Natural Park is a French regional natural park created by decree on 23 May [dated source], whose perimeter occupies approximately 2,282 km2 spread over 64 communes of the three departments of Aveyron, Lozère and Cantal, around the plateau of the same name. It is the 53rd French Regional Natural Park.', 'The Aubrac Regional Natural Park is a French regional natural park covering about 2,282 km2 across 64 communes in the Aveyron, Lozère and Cantal departments, around the Aubrac plateau. It is the 53rd French regional natural park.'),
  ('en', 'parc-naturel-regional-de-guyane', 'seo_description', 'seo_description', null, 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane.', 'A regional natural park in French Guiana spread over six communes, from Iracoubo and Mana to Saint-Georges.'),
  ('en', 'parc-naturel-regional-de-guyane', 'tagline', 'tagline', null, 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane.', 'A regional natural park in French Guiana spread over six communes, from Iracoubo and Mana to Saint-Georges.'),
  ('en', 'parc-naturel-regional-de-guyane', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Guiana Regional Natural Park is a French regional natural park created in [dated source] in Guyane. It is divided into three terrestrial parts and two maritime portions, and covers the territory of six communes: Iracoubo, Mana, Ouanary, Roura, Saint-Georges and Sinnamary.', 'The Guiana Regional Natural Park is a French regional natural park in French Guiana. It is divided into three land areas and two marine areas and covers the territory of six communes: Iracoubo, Mana, Ouanary, Roura, Saint-Georges and Sinnamary.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'seo_description', 'seo_description', null, 'REWRITE', 'This regional nature park was established on January 26, [dated source].', 'A regional nature park on an alpine massif between the Drôme and Hautes-Alpes, covering 104 municipalities.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'tagline', 'tagline', null, 'REWRITE', 'This regional nature park was established on January 26, [dated source].', 'A regional nature park on an alpine massif between the Drôme and Hautes-Alpes, covering 104 municipalities.'),
  ('en', 'parc-naturel-regional-des-baronnies-provencales', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The regional nature park of the Provencal Baronnies extends over an alpine massif between the departments of Drôme and Hautes-Alpes in the south-east of France. This regional nature park was established on January 26, [dated source]. It covers 104 municipalities in whole or in part.', 'The Baronnies Provençales Regional Nature Park extends over an alpine massif between the Drôme and Hautes-Alpes departments in south-east France. It covers 104 municipalities in whole or in part.'),
  ('en', 'parc-naturel-regional-des-prealpes-d-azur', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Parc naturel régional des Préalpes d''Azur is a French regional natural park created on 30 March [dated source] and located in the Alpes-Maritimes department, in the Provence-Alpes-Côte d''Azur region. It is precisely located in the Prealps of Grasse, between the valleys of Siagne, Wolf, Cagne, Esteron and Var.', 'The Parc naturel régional des Préalpes d''Azur is a French regional natural park in the Alpes-Maritimes department of Provence-Alpes-Côte d''Azur. It lies in the Prealps of Grasse, between the valleys of the Siagne, Loup, Cagne, Estéron and Var.'),
  ('en', 'parc-naturel-regional-medoc', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Médoc Regional Natural Park is a regional natural park located in the Gironde department, in the Nouvelle-Aquitaine region, classified by decree of May 24, [dated source]. It becomes France''s 54th regional natural park and covers part of the natural region of Médoc.', 'The Médoc Regional Natural Park lies in the Gironde department of the Nouvelle-Aquitaine region. It is France''s 54th regional natural park and covers part of the Médoc natural region.'),
  ('en', 'parc-naturel-regional-oisepays-de-france', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Oise-Pays de France regional nature park, created on 13 January [dated source] by decree of the Prime Minister, covers 70 communes in the departments of Oise and Val-d''Oise. It is one of the few parks spread over two administrative regions, the fourth PNR of the Hauts de France and the fourth in Île-de-France.', 'The Oise-Pays de France Regional Nature Park covers 70 communes in the Oise and Val-d''Oise departments. It is one of the few parks spread over two administrative regions: the fourth regional natural park of Hauts-de-France and the fourth in Île-de-France.'),
  ('en', 'parco-dei-monti-sicani', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Sicani Mountains park was a regional natural park of Sicily established on 19 December [dated source] and suppressed in July [dated source]. It included 12 municipalities in the territories of the free municipal consortium of Agrigento and the metropolitan city of Palermo, Sicily.', 'The Sicani Mountains park was a regional natural park of Sicily that has since been abolished. It included 12 municipalities in the free municipal consortium of Agrigento and the metropolitan city of Palermo.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'seo_description', 'seo_description', null, 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the', 'A protected natural area along the river Cervaro, about 12 kilometres from Foggia in Apulia.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'tagline', 'tagline', null, 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the', 'A protected natural area along the river Cervaro, about 12 kilometres from Foggia in Apulia.'),
  ('en', 'parco-naturale-regionale-bosco-incoronata', 'travel_plan.days[0].stops[0].detail', 'travel_plan', '{days,0,stops,0,detail}'::text[], 'REWRITE', 'The Regional Natural Park Bosco Incoronata is a protected natural area established in [dated source] along the river Cervaro about 12 kilometers from the city of Foggia, in the heart of the Apulia Tablet.', 'The Bosco Incoronata Regional Natural Park is a protected natural area along the river Cervaro, about 12 kilometres from Foggia, in the heart of the Tavoliere plain of Apulia.'),
